// Response actions a sensor really applies; everything else is a simulation.
const EXECUTED_ACTIONS:Record<string,{label:string;capability:string;min:number;max:number;def:number;target:string}>={block_source_ip:{label:'Real IP block (Windows Firewall)',capability:'response.block_ip',min:5,max:1440,def:60,target:'IP address to block'},isolate_host:{label:'Real host isolation (cuts the sensor computer off the network)',capability:'response.isolate_host',min:5,max:240,def:30,target:''},disable_local_account:{label:'Real local account disable (Windows account on the sensor computer)',capability:'response.disable_account',min:5,max:1440,def:60,target:'Local Windows account name'}}
type User = { id:string; organization_id:string; email:string; full_name:string; roles:string[]; is_active:boolean; auth_methods?:string[] }
type AuthenticatedResponse = { access_token:string; user:User; recovery_codes?:string[]|null }
type MFAChallengeResponse = { mfa_required:true; mfa_setup_required:boolean; challenge_token:string }
type MFAStatus = { enabled:boolean; required_for_organization:boolean; recovery_codes_remaining:number }
type Row = Record<string, any>
type Page<T> = { items:T[]; page:number; page_size:number; total:number }
type Section = 'Overview'|'Detections'|'Cases'|'Events'|'Hosts'|'Network discovery'|'Sensors'|'Ingestion'|'Cloud connectors'|'Notifications'|'Users'|'Rules'|'Audit'|'Settings'
let uiLanguage:Language='en';const t=(text:string)=>translate(text,uiLanguage);const API='/api/v1'; const SENSOR_CONTROL='http://127.0.0.1:8765'; let accessToken=''
async function sensorControl<T>(path:string,init:RequestInit={}):Promise<T>{const res=await fetch(`${SENSOR_CONTROL}${path}`,{...init,headers:{'Content-Type':'application/json',...init.headers},cache:'no-store'});const body=await res.json().catch(()=>({}));if(!res.ok)throw Error(body?.error||'The Windows sensor controller could not complete this request.');return body as T}
async function api<T>(path:string, init:RequestInit={}):Promise<T>{
  const headers=new Headers(init.headers); if(accessToken) headers.set('Authorization',`Bearer ${accessToken}`)
  if(init.body && !(init.body instanceof FormData)) headers.set('Content-Type','application/json')
  let res=await fetch(API+path,{...init,headers,credentials:'include'})
  if(res.status===401 && !['/auth/login','/auth/refresh'].includes(path)){const rr=await fetch(API+'/auth/refresh',{method:'POST',credentials:'include'});if(rr.ok){accessToken=(await rr.json()).access_token;headers.set('Authorization',`Bearer ${accessToken}`);res=await fetch(API+path,{...init,headers,credentials:'include'})}}
 if(!res.ok){const body=await res.json().catch(()=>({}));const fields=body?.error?.details?.fields as {location:string;message:string}[]|undefined;const detail=fields?.map(f=>`${f.location}: ${f.message}`).join('; ');const statusMessage=res.status===502?(uiLanguage==='tr'?'Giriş servisine ulaşılamıyor (502). Uygulama sunucusunu başlatıp yeniden deneyin.':'The sign-in service is unavailable (502). Start the application server and try again.'):null;throw Error([body?.error?.message||statusMessage||`Request failed (${res.status})`,detail].filter(Boolean).join(' — '))}
  if(res.status===204)return undefined as T;return res.json() as Promise<T>
}
function OIDCButton({organizationSlug,onResult,onError}:{organizationSlug:string;onResult:(value:any)=>void;onError:(message:string)=>void}){const[enabled,setEnabled]=useState(false),[ssoOrigin,setSsoOrigin]=useState('');useEffect(()=>{let active=true;api<{enabled:boolean;origin?:string}>('/auth/oidc/status').then(value=>{if(active){setEnabled(value.enabled);setSsoOrigin(value.origin||'')}}).catch(()=>{});return()=>{active=false}},[]);if(!enabled)return null;
 // SSO only works from the address registered with the identity provider: the sign-in cookie and the result message are both tied to that origin.
 if(ssoOrigin&&ssoOrigin!==window.location.origin)return <button type="button" className="secondary wide" onClick={()=>{window.location.href=ssoOrigin}}>Open {ssoOrigin.replace(/^https:\/\//,'')} to use company SSO</button>
 function start(){if(!organizationSlug.trim()){onError('Enter your organization before using single sign-on.');return}const popup=window.open(`${API}/auth/oidc/start?organization_slug=${encodeURIComponent(organizationSlug)}`,'sentinelai-sso','popup,width=520,height=720');if(!popup){onError('Allow the sign-in window to open, then try again.');return}onError('');const listener=(event:MessageEvent)=>{if(event.origin!==window.location.origin||event.source!==popup)return;window.removeEventListener('message',listener);popup.close();if(event.data?.type==='sentinelai-sso-error'){onError(event.data.message||'Company SSO could not be completed.');return}if(event.data?.type!=='sentinelai-sso-result')return;onResult(event.data)};window.addEventListener('message',listener)}return <button type="button" className="secondary wide" onClick={start}>Continue with company SSO</button>}
const nav:{label:Section;icon:any}[]=[{label:'Overview',icon:LayoutDashboard},{label:'Detections',icon:ShieldAlert},{label:'Cases',icon:BriefcaseBusiness},{label:'Events',icon:Activity},{label:'Hosts',icon:Server},{label:'Network discovery',icon:Network},{label:'Sensors',icon:Activity},{label:'Ingestion',icon:FileUp},{label:'Cloud connectors',icon:Cloud},{label:'Notifications',icon:Bell},{label:'Users',icon:UsersIcon},{label:'Rules',icon:BookOpen},{label:'Audit',icon:Fingerprint}]
const cls=(s='')=>`severity ${s.toLowerCase()}`;const date=(v?:string)=>v?new Date(v).toLocaleString(uiLanguage==='tr'?'tr-TR':'en-US'):'—';const telemetryRecent=(v?:string)=>{if(!v)return false;const age=Date.now()-new Date(v).getTime();return age>=-60000&&age<=120000};const eventLabel=(type?:string)=>({ 'net.conn':'Network connection','auth.success':'Successful sign-in','auth.failure':'Failed sign-in','process.start':'Program started','dns.query':'DNS query','windows.remote_logon':'Remote Desktop sign-in','cloud.aws.cloudtrail':'AWS CloudTrail activity','cloud.azure.activity':'Azure activity','microsoft.entra.signin':'Microsoft Entra sign-in' } as Record<string,string>)[type||'']||(type?type.replace(/[._]/g,' ').replace(/\b\w/g,c=>c.toUpperCase()):'Security event');const eventTypeSummary=(types:Record<string,number>={})=>Object.entries(types).map(([type,count])=>`${eventLabel(type)} (${count})`).join(', ')||'—'
const eventSourceLabel=(event:Row)=>{const type=String(event.event_type||'');if(type==='cloud.aws.cloudtrail')return 'AWS CloudTrail';if(type==='cloud.azure.activity')return 'Azure Activity';if(type==='microsoft.entra.signin')return 'Microsoft Entra';const sourceType=String(event.source_type||'').toLowerCase();const eventSource=String(event.attributes?.source_name||'').toLowerCase();if(sourceType==='host_packet_headers'||sourceType==='windows_host_sensor'||sourceType==='windows'||type==='process.start'||event.attributes?.windows_event_id!==undefined||eventSource==='windows.security')return 'Windows endpoint';if(type==='net.conn'||type==='dns.query')return 'Network';return event.source_name||event.source_type||'Imported telemetry'}

function UploadRetentionSettings({user,setError}:{user:User;setError:(message:string)=>void}){const[days,setDays]=useState(30),[busy,setBusy]=useState(false),[saved,setSaved]=useState(false);useEffect(()=>{api<{upload_retention_days:number}>('/settings').then(value=>setDays(value.upload_retention_days)).catch(error=>setError(error instanceof Error?error.message:'Unable to load upload retention setting'))},[setError]);if(!user.roles.includes('administrator'))return null;async function save(){setBusy(true);setSaved(false);try{const value=await api<{upload_retention_days:number}>('/settings',{method:'PATCH',body:JSON.stringify({upload_retention_days:days})});setDays(value.upload_retention_days);setSaved(true)}catch(error){setError(error instanceof Error?error.message:'Unable to save upload retention setting')}finally{setBusy(false)}}return <div className="content"><section className="panel preferences"><div className="panel-head"><div><h2>Imported source-file retention</h2><p>Completed and failed import files are automatically removed after this many days. Ingestion jobs, normalized events, detections, cases, and audit history follow their own retention rules.</p></div></div><div className="preference-grid"><label>Keep original import files (days)<input type="number" min={1} max={3650} value={days} onChange={event=>{setDays(Number(event.target.value));setSaved(false)}}/></label><button className="primary" disabled={busy||days<1||days>3650} onClick={()=>void save()}>{busy?'Saving…':'Save retention period'}</button>{saved&&<p className="preferences-note"><Check size={15}/>Retention period saved. Expired files are removed by the daily cleanup task.</p>}</div><small>Default: 30 days. Allowed range: 1–3650 days.</small></section></div>}

export default function App(){
 const[user,setUser]=useState<User|null>(null),[restoring,setRestoring]=useState(true),[section,setSection]=useState<Section>('Overview'),[error,setError]=useState(''),[busy,setBusy]=useState(false)
 const[language,setLanguage]=useState<Language>(()=>localStorage.getItem('sentinel-language')==='tr'?'tr':'en'),[theme,setTheme]=useState<Theme>(()=>{const saved=localStorage.getItem('sentinel-theme');return saved==='light'||saved==='contrast'?saved:'dark'})
 uiLanguage=language;useEffect(()=>{document.documentElement.lang=language==='tr'?'tr':'en';document.documentElement.dataset.theme=theme;localStorage.setItem('sentinel-language',language);localStorage.setItem('sentinel-theme',theme)},[language,theme])
 useEffect(()=>{api<{access_token:string;user:User}>('/auth/refresh',{method:'POST'}).then(r=>{accessToken=r.access_token;setUser(r.user)}).catch(()=>{}).finally(()=>setRestoring(false))},[])
 async function logout(){try{await api('/auth/logout',{method:'POST'})}catch{}accessToken='';setUser(null)}
  // Response proposals waiting for a decision; polled so a second administrator notices without opening each case.
  const[approvals,setApprovals]=useState<{items:Record<string,any>[];waiting_for_me:number}>({items:[],waiting_for_me:0})
  const loadApprovals=useCallback(()=>{if(!user||!user.roles.some(role=>role==='administrator'||role==='analyst'||role==='auditor')){setApprovals({items:[],waiting_for_me:0});return}api<{items:Record<string,any>[];waiting_for_me:number}>('/cases/pending-approvals').then(setApprovals).catch(()=>{})},[user])
  useEffect(()=>{loadApprovals();const timer=window.setInterval(loadApprovals,20000);return()=>window.clearInterval(timer)},[loadApprovals])
 if(restoring)return <div className="splash"><Shield/> Loading secure workspace…</div>
 if(!user)return <Login onLogin={setUser}/>
 return <div className="shell"><aside className="sidebar"><div className="brand"><div className="brand-icon"><Shield/></div><div><b>Sentinel<span>AI</span></b><small>EXTENDED DETECTION</small></div></div><div className="workspace"><i/> {translate('LOCAL LAB',language)} <ChevronDown size={13}/></div><div className="nav-caption">{translate('WORKSPACE',language)}</div><nav>{nav.filter(item=>item.label!=='Users'||user.roles.includes('administrator')).filter(item=>item.label!=='Network discovery'||user.roles.some(role=>role==='administrator'||role==='analyst')).map(n=><button key={n.label} className={`nav-item ${section===n.label?'active':''}`} onClick={()=>{setSection(n.label);setError('')}}><n.icon size={17}/>{translate(n.label,language)}{n.label==='Detections'&&<em>!</em>}{n.label==='Cases'&&approvals.items.length>0&&<em title="Response proposals waiting for approval">{approvals.items.length}</em>}</button>)}</nav><div className="side-bottom"><div className="lab-note"><b><Shield size={14}/> {translate('Lab mode',language)}</b><p>{translate('Automated response is disabled. Findings require analyst review.',language)}</p></div><button className={`nav-item ${section==='Settings'?'active':''}`} onClick={()=>setSection('Settings')}><Settings size={17}/> {translate('Settings',language)}</button><div className="profile"><div className="avatar">{(user.full_name||user.email)[0].toUpperCase()}</div><div className="profile-text"><b>{user.full_name||user.email}</b><small>{user.roles.join(' · ')}</small></div><button title={translate('Sign out',language)} onClick={logout}><LogOut size={16}/></button></div></div></aside><main className="main"><header><div>{translate('Security operations',language)} <span>/</span> <b>{translate(section,language)}</b></div><div className="top-right"><div className="dev-label"><i/> {translate('DEVELOPMENT LAB',language)}</div><button title="Help"><CircleHelp size={17}/></button><button title="Notifications"><Bell size={17}/></button><div className="avatar mini">{(user.full_name||user.email)[0].toUpperCase()}</div></div></header>{error&&<div className="toast"><AlertTriangle size={16}/>{error}<button onClick={()=>setError('')}><X size={15}/></button></div>}{section==='Settings'?<><Preferences language={language} theme={theme} user={user} onLanguage={setLanguage} onTheme={setTheme} onUser={setUser} onLogout={()=>{accessToken='';setUser(null)}} setError={setError}/><UploadRetentionSettings user={user} setError={setError}/></>:<>{(section==='Overview'||section==='Cases')&&approvals.items.length>0&&<div className="content approvals-banner"><PendingApprovals items={approvals.items} language={language} setError={setError} apiRequest={api} reload={loadApprovals}/></div>}<Workspace section={section} user={user} setError={setError} busy={busy} setBusy={setBusy} setSection={setSection} apiRequest={api} language={language}/></>}<footer>SentinelAI XDR <span>·</span> {translate('Local defensive monitoring',language)} <span>·</span> {translate('Findings are signals for investigation, not proof of compromise.',language)}</footer></main></div>
}

function Preferences({language,theme,user,onLanguage,onTheme,onUser,onLogout,setError}:{language:Language;theme:Theme;user:User;onLanguage:(v:Language)=>void;onTheme:(v:Theme)=>void;onUser:(user:User)=>void;onLogout:()=>void;setError:(message:string)=>void}){const[status,setStatus]=useState<MFAStatus|null>(null),[password,setPassword]=useState(''),[code,setCode]=useState(''),[secret,setSecret]=useState(''),[busy,setBusy]=useState(false),[recovery,setRecovery]=useState<string[]>([]);useEffect(()=>{api<MFAStatus>('/auth/mfa/status').then(setStatus).catch(e=>setError(e instanceof Error?e.message:'Unable to load MFA status'))},[setError]);async function begin(){setBusy(true);try{const result=await api<{secret:string}>('/auth/mfa/enroll',{method:'POST',body:JSON.stringify({current_password:password})});setSecret(result.secret)}catch(e){setError(e instanceof Error?e.message:'Unable to start MFA enrollment')}finally{setBusy(false)}}async function enable(){setBusy(true);try{const result=await api<AuthenticatedResponse>('/auth/mfa/enable',{method:'POST',body:JSON.stringify({code})});accessToken=result.access_token;onUser(result.user);setRecovery(result.recovery_codes||[]);setSecret('');setCode('');setPassword('');setStatus({enabled:true,required_for_organization:status?.required_for_organization||false,recovery_codes_remaining:result.recovery_codes?.length||0})}catch(e){setError(e instanceof Error?e.message:'Unable to enable MFA')}finally{setBusy(false)}}async function disable(){setBusy(true);try{await api('/auth/mfa/disable',{method:'POST',body:JSON.stringify({current_password:password,code})});onLogout()}catch(e){setError(e instanceof Error?e.message:'Unable to disable MFA')}finally{setBusy(false)}}async function setRequired(required:boolean){setBusy(true);try{await api('/auth/mfa/requirement',{method:'PATCH',body:JSON.stringify({required})});if(required){onLogout();return}setStatus(status?{...status,required_for_organization:false}:status)}catch(e){setError(e instanceof Error?e.message:'Unable to update organization MFA policy')}finally{setBusy(false)}}return <div className="content"><Heading eyebrow={translate('Preferences',language)} title={translate('Settings',language)} desc={translate('Choose how SentinelAI looks and which language it uses.',language)}/><section className="panel preferences"><div className="panel-head"><div><h2>{translate('Display preferences',language)}</h2><p>{translate('Changes apply immediately and are remembered on this browser.',language)}</p></div></div><div className="preference-grid"><label>{translate('Interface language',language)}<select value={language} onChange={e=>onLanguage(e.target.value as Language)}><option value="en">English</option><option value="tr">Türkçe</option></select></label><label>{translate('Theme',language)}<select value={theme} onChange={e=>onTheme(e.target.value as Theme)}><option value="dark">{translate('Dark',language)}</option><option value="light">{translate('Light',language)}</option><option value="contrast">{translate('High contrast',language)}</option></select></label></div><p className="preferences-note"><Shield size={15}/>{translate('Saved on this browser',language)}</p></section><section className="panel preferences"><div className="panel-head"><div><h2>Multi-factor authentication</h2><p>Use a TOTP authenticator such as Microsoft Authenticator, Google Authenticator, or 1Password.</p></div><span>{status?.enabled?'ENABLED':'NOT ENABLED'}</span></div>{status?.required_for_organization&&<p className="preferences-note"><Shield size={15}/>Your organization requires MFA for every user.</p>}{recovery.length>0?<div><p>Save these recovery codes securely. Each code works once, and they will not be shown again.</p><pre className="recovery-codes">{recovery.join('\n')}</pre><button className="primary" onClick={()=>setRecovery([])}>I saved my recovery codes</button></div>:status?.enabled?<div className="preference-grid"><label>Current password<input type="password" autoComplete="current-password" value={password} onChange={e=>setPassword(e.target.value)}/></label><label>Authenticator or recovery code<input value={code} onChange={e=>setCode(e.target.value)} autoComplete="one-time-code"/></label><button className="secondary" disabled={busy||!password||!code} onClick={()=>void disable()}>Disable MFA</button><p className="preferences-note">{status.recovery_codes_remaining} recovery codes remain.</p></div>:secret?<div className="preference-grid"><p>In your authenticator choose “enter setup key” and enter this secret:</p><code>{secret}</code><label>Verification code<input value={code} onChange={e=>setCode(e.target.value)} autoComplete="one-time-code"/></label><button className="primary" disabled={busy||code.length<6} onClick={()=>void enable()}>{busy?'Enabling…':'Verify and enable MFA'}</button></div>:<div className="preference-grid"><label>Current password<input type="password" autoComplete="current-password" value={password} onChange={e=>setPassword(e.target.value)}/></label><button className="primary" disabled={busy||password.length<1} onClick={()=>void begin()}>{busy?'Starting…':'Set up MFA'}</button></div>}{user.roles.includes('administrator')&&<div className="preference-grid"><label><input type="checkbox" checked={status?.required_for_organization||false} disabled={!status||busy||!status.enabled||!user.auth_methods?.includes('otp')} onChange={e=>void setRequired(e.target.checked)}/> Require MFA for this organization (signs everyone out)</label><small>Enable this only after you have signed in using your authenticator.</small></div>}</section></div>}

function Login({onLogin}:{onLogin:(u:User)=>void}){const[organizationSlug,setOrganizationSlug]=useState('default'),[email,setEmail]=useState('admin@localhost.local'),[password,setPassword]=useState(''),[code,setCode]=useState(''),[challenge,setChallenge]=useState(''),[setupSecret,setSetupSecret]=useState(''),[recoveryCodes,setRecoveryCodes]=useState<string[]>([]),[pendingAuth,setPendingAuth]=useState<AuthenticatedResponse|null>(null),[error,setError]=useState(''),[busy,setBusy]=useState(false);function finish(result:AuthenticatedResponse){setChallenge('');if(result.recovery_codes?.length){setPendingAuth(result);setRecoveryCodes(result.recovery_codes)}else{accessToken=result.access_token;onLogin(result.user)}}function handleSso(result:any){if(result.mfa_required){setChallenge(result.challenge_token);if(result.mfa_setup_required){api<{secret:string}>('/auth/mfa/setup',{method:'POST',body:JSON.stringify({challenge_token:result.challenge_token})}).then(value=>setSetupSecret(value.secret)).catch(e=>setError(e instanceof Error?e.message:'Unable to start MFA setup'))}}else finish(result as AuthenticatedResponse)}async function submit(e:React.FormEvent){e.preventDefault();setBusy(true);setError('');try{const result=await api<AuthenticatedResponse|MFAChallengeResponse>('/auth/login',{method:'POST',body:JSON.stringify({organization_slug:organizationSlug,email,password})});if('mfa_required'in result){setChallenge(result.challenge_token);if(result.mfa_setup_required){const setup=await api<{secret:string}>('/auth/mfa/setup',{method:'POST',body:JSON.stringify({challenge_token:result.challenge_token})});setSetupSecret(setup.secret)}}else finish(result)}catch(e){setError(e instanceof Error?e.message:'Unable to sign in')}finally{setBusy(false)}}async function verify(e:React.FormEvent){e.preventDefault();setBusy(true);setError('');try{finish(await api<AuthenticatedResponse>('/auth/mfa/verify',{method:'POST',body:JSON.stringify({challenge_token:challenge,code})}))}catch(e){setError(e instanceof Error?e.message:'Unable to verify MFA')}finally{setBusy(false)}}async function confirmSetup(e:React.FormEvent){e.preventDefault();setBusy(true);setError('');try{finish(await api<AuthenticatedResponse>('/auth/mfa/setup/confirm',{method:'POST',body:JSON.stringify({challenge_token:challenge,code})}))}catch(e){setError(e instanceof Error?e.message:'Unable to enable MFA')}finally{setBusy(false)}}if(recoveryCodes.length&&pendingAuth)return <div className="login-page"><section className="login-card"><div className="eyebrow">{t('SAVE THESE CODES')}</div><h1>{t('MFA is enabled')}</h1><p>{t('Store these recovery codes somewhere safe. Each works once.')}</p><pre className="recovery-codes">{recoveryCodes.join('\n')}</pre><button className="primary wide" onClick={()=>{accessToken=pendingAuth.access_token;onLogin(pendingAuth.user)}}>{t('I saved my codes — continue')}</button></section></div>;const submitChallenge=setupSecret?confirmSetup:verify;return <div className="login-page"><div className="login-art"><div className="glow-ring ring-a"/><div className="glow-ring ring-b"/><div className="login-floats" aria-hidden="true"><span>{t('Clear security overview')}</span><span>{t('Easy-to-review alerts')}</span><span>{t('Analyst-guided response')}</span></div><div className="login-shield"><Shield size={42}/></div><div className="login-wordmark">SENTINEL<span>AI</span></div><p>{t('Extended detection and response')}<br/>{t('for your local security lab.')}</p><small>{t('DEFENSIVE MONITORING · ANALYST LED')}</small></div><form className="login-card" onSubmit={challenge?submitChallenge:submit}><div className="eyebrow">{t('SECURE ACCESS')}</div><h1>{challenge?(setupSecret?t('Set up multi-factor authentication'):t('Verify your identity')):t('Welcome back')}</h1><p>{challenge?t('Enter the current code from your authenticator app.'):t('Sign in to your SentinelAI workspace.')}</p>{error&&<div className="form-error"><AlertTriangle size={16}/>{error}</div>}{!challenge?<><label>{t('Organization')}<input autoComplete="organization" required value={organizationSlug} onChange={e=>setOrganizationSlug(e.target.value.toLowerCase())}/></label><label>{t('Email address')}<input type="email" autoComplete="username" required value={email} onChange={e=>setEmail(e.target.value)}/></label><label>{t('Password')}<input type="password" autoComplete="current-password" required value={password} onChange={e=>setPassword(e.target.value)}/></label></>:<>{setupSecret&&<div><p>{t('Enter this setup key in your authenticator app:')}</p><code>{setupSecret}</code></div>}<label>{t(setupSecret?'Authenticator code':'Authenticator or recovery code')}<input autoComplete="one-time-code" required value={code} onChange={e=>setCode(e.target.value)}/></label></>}<button className="primary wide" disabled={busy}>{busy?(challenge?t('Verifying…'):t('Signing in…')):challenge?(setupSecret?t('Enable MFA'):t('Verify code')):t('Sign in securely')} <ArrowDownToLine size={16}/></button>{!challenge&&<OIDCButton organizationSlug={organizationSlug} onResult={handleSso} onError={setError}/>}{!challenge&&<div className="hint"><Shield size={14}/> {t('Development credentials are set in your local .env file.')}</div>}</form></div>}

function Workspace({section,user,setError,busy,setBusy,setSection,apiRequest,language}:{section:Section;user:User;setError:(s:string)=>void;busy:boolean;setBusy:(b:boolean)=>void;setSection:(section:Section)=>void;apiRequest:(path:string,init?:RequestInit)=>Promise<any>;language:Language}){if(section==='Overview')return <Overview setError={setError} setSection={setSection}/>;if(section==='Ingestion')return <Ingestion setError={setError} busy={busy} setBusy={setBusy}/>;if(section==='Sensors')return <SensorControl user={user} setError={setError}/>;if(section==='Network discovery')return <NetworkDiscovery setError={setError}/>;if(section==='Cloud connectors')return <CloudConnectors user={user} language={language} setError={setError} apiRequest={apiRequest}/>;if(section==='Notifications')return <Notifications user={user} language={language} setError={setError} apiRequest={apiRequest}/>;if(section==='Users')return <Users user={user} language={language} setError={setError} apiRequest={apiRequest}/>;return <DataView key={section} section={section} user={user} setError={setError}/>}
function Heading({eyebrow,title,desc,action}:{eyebrow:string;title:string;desc:string;action?:React.ReactNode}){return <div className="heading"><div><div className="eyebrow">{t(eyebrow)}</div><h1>{t(title)}</h1><p>{t(desc)}</p></div>{action}</div>}
function Metric({icon:Icon,label,value,note,tone}:{icon:any;label:string;value:number;note:string;tone:string}){return <div className="metric"><div className={`metric-icon ${tone}`}><Icon size={18}/></div><div className="metric-copy"><small>{t(label)}</small><strong>{value.toLocaleString(uiLanguage==='tr'?'tr-TR':'en-US')}</strong><span>{t(note)}</span></div><div className={`metric-art ${tone}`}/></div>}
function Empty({text}:{text:string}){return <div className="empty"><div><Search size={18}/></div><p>{t(text)}</p></div>}
function Overview({setError,setSection}:{setError:(s:string)=>void;setSection:(section:Section)=>void}){
 const[data,setData]=useState<Row|null>(null),[dets,setDets]=useState<Row[]>([]),[events,setEvents]=useState<Row[]>([]),[sessions,setSessions]=useState<Row[]>([]),[loading,setLoading]=useState(true)
 const load=useCallback(async()=>{setLoading(true);try{const[s,d,e,ss]=await Promise.all([api<Row>('/dashboard/summary'),api<Page<Row>>('/detections?page_size=6'),api<Page<Row>>('/events?page_size=5'),api<Row[]>('/ingest/live/sessions?page_size=25')]);setData(s);setDets(d.items);setEvents(e.items);setSessions(ss)}catch(error){setError(error instanceof Error?error.message:'Unable to load overview')}finally{setLoading(false)}},[setError])
 useEffect(()=>{void load();const timer=window.setInterval(()=>void load(),15000);return()=>window.clearInterval(timer)},[load])
 const online=sessions.filter(row=>row.state==='online').length
 const high=dets.filter(row=>['high','critical'].includes(String(row.severity).toLowerCase())).length
 const connectionSummary=(event:Row)=>event.event_type==='net.conn'?`${event.src_ip||t('Unknown address')} → ${event.dst_ip||t('Unknown address')}${event.dst_port?` · ${t('Target port')} ${event.dst_port}`:''}`:event.event_type?.startsWith('auth.')?`${t('Account')}: ${event.attributes?.username||t('Not available')} · ${event.attributes?.outcome||eventLabel(event.event_type)}`:event.event_type==='process.start'?`${t('Program')}: ${event.attributes?.process_name?.split(/[\\/]/).pop()||t('Not available')}`:`${event.host_id||t('Unknown device')} · ${date(event.event_time)}`
 return <div className="content overview-content"><div className="overview-hero"><div className="overview-orbit overview-orbit-a"/><div className="overview-orbit overview-orbit-b"/><div className="overview-planet"/><div className="overview-hero-content"><div className="eyebrow">{t('DAILY SECURITY SUMMARY')}</div><h1>{t('Your security, at a glance.')}</h1><p>{online>0?t('Your sensors are reporting. Here is what may need your attention.'):t('Review your workspace status and the latest security findings.')}</p><div className="overview-hero-actions"><button className="primary" onClick={()=>setSection('Detections')}>{t('Review findings')} <ArrowDownToLine size={15}/></button><span className="overview-live"><i/> {online>0?`${online} ${t('sensors reporting')}`:t('No sensor is currently reporting')}</span></div></div></div>
 {loading&&!data?<Empty text={t('Loading workspace data…')}/>:<><div className="metrics overview-metrics"><Metric icon={Activity} label="Events ingested" value={data?.event_count||0} note="All stored events" tone="blue"/><Metric icon={ShieldAlert} label="Findings to review" value={data?.detection_count||0} note={high?`${high} ${t('high priority in latest findings')}`:'Review the latest findings'} tone="amber"/><Metric icon={BriefcaseBusiness} label="Open cases" value={data?.open_cases||0} note="New or being investigated" tone="purple"/><Metric icon={Server} label="Sensors reporting" value={online} note={`${sessions.length} ${t('registered sensor sessions')}`} tone="green"/></div><div className="dash-grid overview-grid"><section className="panel"><div className="panel-head"><div><h2>{t('Recent findings')}</h2><p>{t('Plain-language signals that may need review')}</p></div><button className="secondary" onClick={()=>setSection('Detections')}>{t('View all')} →</button></div>{dets.length?<div className="overview-list">{dets.slice(0,4).map(finding=><article className="overview-row" key={finding.id}><span className={`overview-mark ${String(finding.severity).toLowerCase()}`}/><div className="overview-row-copy"><b>{finding.title}</b><small>{finding.summary||t('A security rule noticed an unusual activity.')}</small>{finding.evidence?.src_ip&&<small>{t('Related address')}: <code>{finding.evidence.src_ip}</code></small>}</div><span className={cls(finding.severity)}>{t(finding.severity?.toUpperCase()||'')}</span></article>)}</div>:<Empty text={t('No detections yet. Import sample telemetry to get started.')}/>}</section><section className="panel"><div className="panel-head"><div><h2>{t('Recent activity')}</h2><p>{t('What the sensors observed')}</p></div><button className="secondary" onClick={()=>setSection('Events')}>{t('View all')} →</button></div>{events.length?<div className="overview-list">{events.slice(0,4).map(event=><article className="overview-row activity" key={event.id}><span className="overview-activity-icon"><Activity size={15}/></span><div className="overview-row-copy"><b>{t(eventLabel(event.event_type))}</b><small>{connectionSummary(event)}</small><small>{event.host_id||t('Unknown device')} · {date(event.event_time)}</small></div></article>)}</div>:<Empty text={t('No recent events yet.')}/>}</section></div><div className="disclaimer"><Shield size={16}/><span><b>{t('What these numbers mean')}</b> {t('These are monitoring signals to review, not proof that an attack happened. SentinelAI does not automatically block devices or accounts.')}</span></div></>}
 </div>
}
function Ingestion({setError,busy,setBusy}:{setError:(s:string)=>void;busy:boolean;setBusy:(b:boolean)=>void}){const[jobs,setJobs]=useState<Row[]>([]),[adapter,setAdapter]=useState('generic_json'),[file,setFile]=useState<File|null>(null);const load=useCallback(async()=>{try{setJobs((await api<Page<Row>>('/ingest/jobs?page_size=30')).items)}catch(e){setError(e instanceof Error?e.message:'Unable to load jobs')}},[setError]);useEffect(()=>{void load();const timer=window.setInterval(()=>void load(),5000);return()=>window.clearInterval(timer)},[load]);async function upload(e:React.FormEvent){e.preventDefault();if(!file)return;setBusy(true);try{const form=new FormData();form.append('file',file);form.append('adapter',adapter);await api('/ingest/upload',{method:'POST',body:form});setFile(null);await load()}catch(e){setError(e instanceof Error?e.message:'Upload failed')}finally{setBusy(false)}}return <div className="content"><Heading eyebrow="TELEMETRY PIPELINE" title="Ingestion" desc="Import authorized log files and review processing jobs. Live sensor events appear in Events and Hosts."/><section className="panel guide"><div className="panel-head"><div><h2>Windows host sensor</h2><p>Start and stop the Windows sensor from the Sensors page. Use this page to import log files and review ingestion jobs.</p></div><Activity size={18}/></div><div className="guide-item"><i>01</i><div><b>Install Npcap and sensor dependencies</b><p>See <code>sensor/README.md</code> in the project folder. Run PowerShell as Administrator.</p></div></div><div className="guide-item"><i>02</i><div><b>Select your network adapter</b><p>Start and stop capture in the <b>Sensors</b> page. Choose the active Wi-Fi or Ethernet adapter. Windows sign-in and process collection are optional and require their audit policies as described in the sensor guide.</p></div></div><div className="guide-item"><i>03</i><div><b>Watch events and detections</b><p><code>net.conn</code> records are network signals; <code>auth.success</code> and <code>auth.failure</code> are Windows Security logon signals; <code>process.start</code> shows process and parent names. Open Events and Detections while the sensor is forwarding.</p></div></div></section><div className="ingest-grid"><form className="panel upload-panel" onSubmit={upload}><div className="panel-head"><div><h2>Import telemetry</h2><p>JSON, JSON Lines, or CSV · max 10 MiB</p></div><Upload size={18}/></div><label className="file-drop"><input type="file" accept=".json,.csv,.log" onChange={e=>setFile(e.target.files?.[0]||null)}/><span><FileUp size={22}/></span><b>{file?.name||'Choose a file or drop it here'}</b><small>{file?`${(file.size/1024).toFixed(0)} KB selected`:'Accepted: JSON, CSV, Zeek/Suricata, CloudTrail, Azure Activity, Entra sign-in'}</small></label><label className="field-label">Parser adapter<select value={adapter} onChange={e=>setAdapter(e.target.value)}><option value="generic_json">Generic JSON</option><option value="generic_csv">Generic CSV</option><option value="zeek_json">Zeek conn.log JSON</option><option value="suricata_eve">Suricata EVE JSON</option><option value="aws_cloudtrail">AWS CloudTrail JSON</option><option value="azure_activity">Azure Activity Log JSON</option><option value="entra_signin">Microsoft Entra sign-in JSON</option></select></label><button className="primary" disabled={!file||busy}><Upload size={15}/>{busy?'Uploading…':'Upload and process'}</button></form><section className="panel guide"><div className="panel-head"><div><h2>Input guide</h2><p>What to expect from an import</p></div></div>{[['01','Validate the source','Import telemetry only from systems you are authorized to monitor.'],['02','Review the job','Malformed records are quarantined and summarized in job results.'],['03','Investigate findings','Rule thresholds are lab defaults; confirm evidence before conclusions.']].map(([n,t,p])=><div className="guide-item" key={n}><i>{n}</i><div><b>{t}</b><p>{p}</p></div></div>)}</section></div><section className="panel jobs"><div className="panel-head"><div><h2>Recent jobs</h2><p>Processing history from this workspace</p></div><button className="icon-button" onClick={()=>void load()}><RefreshCw size={16}/></button></div>{jobs.length?<div className="table-wrap"><table><thead><tr><th>FILE</th><th>ADAPTER</th><th>STATUS</th><th>RESULT</th><th>STARTED</th></tr></thead><tbody>{jobs.map(j=><tr key={j.id}><td><b>{j.original_filename}</b></td><td>{j.adapter}</td><td><span className={`status ${j.status}`}>{j.status}</span></td><td>{j.stats?.accepted||0} accepted · {j.stats?.quarantined||0} quarantined</td><td>{date(j.started_at||j.created_at)}</td></tr>)}</tbody></table></div>:<Empty text="No ingestion jobs yet."/>}</section></div>}

function SensorControl({user,setError}:{user:User;setError:(s:string)=>void}){
 const[controller,setController]=useState<Row|null>(null),[adapters,setAdapters]=useState<Row[]>([]),[sessions,setSessions]=useState<Row[]>([]),[selected,setSelected]=useState(''),[windowsEvents,setWindowsEvents]=useState(false),[processEvents,setProcessEvents]=useState(false),[endpointEvents,setEndpointEvents]=useState(false),[enforceBlocks,setEnforceBlocks]=useState(false),[allowIsolation,setAllowIsolation]=useState(false),[allowAccountDisable,setAllowAccountDisable]=useState(false),[busy,setBusy]=useState(false),[message,setMessage]=useState(''),[failure,setFailure]=useState(false)
 const refresh=useCallback(async()=>{try{const status=await sensorControl<Row>('/status');setController(status);if(status.last_error){setFailure(true);setMessage(status.last_error)}const result=await sensorControl<{items:Row[]}>('/interfaces');setAdapters(result.items);setSelected(current=>result.items.some(item=>item.capture_interface===current)?current:(result.items.find(item=>/Wi.?Fi/i.test(item.display_name)&&item.addresses?.some((address:string)=>!address.startsWith('169.254.')&&!address.startsWith('fe80:')))?.capture_interface||result.items.find(item=>item.addresses?.some((address:string)=>!address.startsWith('169.254.')&&!address.startsWith('fe80:')))?.capture_interface||result.items[0]?.capture_interface||''))}catch{setController(null);setAdapters([]);setSelected('')}try{setSessions(await api<Row[]>('/ingest/live/sessions?page_size=50'))}catch(e){setError(e instanceof Error?e.message:'Unable to load sensor sessions')}},[setError])
 useEffect(()=>{void refresh();const timer=window.setInterval(()=>void refresh(),4000);return()=>window.clearInterval(timer)},[refresh])
 const hostSource=controller?.host_name?`${controller.host_name}-live-sensor`:''
 const existingOnline=Boolean(sessions.some(row=>row.state==='online'&&((controller?.sensor_id&&row.sensor_id===controller.sensor_id)||row.source_name===hostSource)))
 async function start(){setBusy(true);setFailure(false);setMessage('Starting sensor and waiting for its first API heartbeat…');try{await sensorControl('/capture/start',{method:'POST',body:JSON.stringify({interface:selected,windows_events:windowsEvents,process_events:processEvents,endpoint_events:endpointEvents,enforce_blocks:enforceBlocks,allow_isolation:allowIsolation,allow_account_disable:allowAccountDisable})});for(let attempt=0;attempt<20;attempt++){const status=await sensorControl<Row>('/status');setController(status);if(status.last_error)throw Error(status.last_error);if(!status.running)throw Error('The sensor process exited before it could report in. Check Npcap, adapter permissions, and the sensor log.');const latest=await api<Row[]>('/ingest/live/sessions?page_size=50');setSessions(latest);const session=latest.find(row=>row.sensor_id===status.sensor_id&&row.state==='online');if(session){setFailure(false);setMessage('Sensor is online on '+selected+'. '+(session.stats?.accepted||0)+' records received so far.');return}await new Promise(resolve=>window.setTimeout(resolve,500))}throw Error('The sensor process is running but has not reported its first heartbeat. Check the API connection and sensor credentials.')}catch(e){setFailure(true);setMessage(e instanceof TypeError?'Cannot reach the local sensor controller. Open the app at http://127.0.0.1:8080 and make sure the elevated controller is still running.':e instanceof Error?e.message:'Could not start the sensor.')}finally{await refresh();setBusy(false)}}
 async function stop(){setBusy(true);setFailure(false);setMessage('');try{const result=await sensorControl<Row>('/capture/stop',{method:'POST',body:'{}'});setMessage(result.message||'Stopping sensor and finishing queued records…');await refresh()}catch(e){setMessage(e instanceof Error?e.message:'Could not stop the sensor.')}finally{setBusy(false)}}
 const active=controller?.running===true
 return <div className="content"><Heading eyebrow="SENSOR HEALTH" title="Sensors" desc="Start or stop this computer’s passive sensor and watch its live heartbeat."/><section className="panel sensor-control"><div className="panel-head"><div><h2>Windows host sensor</h2><p>Captures only traffic visible to this computer’s selected network adapter.</p></div><span className={`status ${active?'completed':controller?'disabled':'processing'}`}>{active?'Controller running':controller?'Controller ready':'Controller unavailable'}</span></div>{!controller&&<div className="sensor-setup"><div><b>One-time setup</b><p>The secure local bridge must run on your Windows computer so the dashboard can control its network card. Open PowerShell as Administrator in the project folder and run:</p><code>.\start_sensor_controller.ps1</code><small>Leave that window open or minimized while using the buttons here, then refresh this page.</small></div></div>}<div className="sensor-controls"><label className="field-label">Network adapter<select value={selected} onChange={event=>setSelected(event.target.value)} disabled={!controller||active||busy}><option value="">Select an active adapter…</option>{adapters.map(item=><option key={item.capture_interface} value={item.capture_interface}>{item.display_name}{item.addresses?.length?` · ${item.addresses.join(', ')}`:' · no IP address'}</option>)}</select></label><div className="sensor-options"><label><input type="checkbox" checked={windowsEvents} onChange={event=>setWindowsEvents(event.target.checked)} disabled={active||busy}/> Include new Windows sign-in events</label><label><input type="checkbox" checked={processEvents} onChange={event=>setProcessEvents(event.target.checked)} disabled={active||busy}/> Include process starts (4688 audit required)</label><label><input type="checkbox" checked={endpointEvents} onChange={event=>setEndpointEvents(event.target.checked)} disabled={active||busy}/> Include Windows account/group, service, task and security changes (e.g. 4720, 4732, 4697, 4698, 4719, 1102)</label><label><input type="checkbox" checked={enforceBlocks} onChange={event=>setEnforceBlocks(event.target.checked)} disabled={active||busy}/> Allow this computer to apply approved IP blocks in Windows Firewall (time-limited; its own addresses, gateway and DNS are never blocked)</label><label><input type="checkbox" checked={allowIsolation} onChange={event=>setAllowIsolation(event.target.checked)} disabled={active||busy}/> Allow this computer to be isolated from the network when approved (time-limited; only the SentinelAI server stays reachable, and it is lifted if the sensor stops)</label><label><input type="checkbox" checked={allowAccountDisable} onChange={event=>setAllowAccountDisable(event.target.checked)} disabled={active||busy}/> Allow approved disabling of a local Windows account on this computer (time-limited; built-in accounts, your own account and the last administrator are never disabled)</label></div><div className="sensor-actions">{!active?<button className="primary" onClick={()=>void start()} disabled={!controller||!selected||busy||existingOnline}><Play size={15}/>{busy?'Starting…':'Start sensor'}</button>:<button className="sensor-stop" onClick={()=>void stop()} disabled={busy}><Square size={14}/>{busy?'Stopping…':'Stop sensor'}</button>}<button className="secondary" onClick={()=>void refresh()} disabled={busy}><RefreshCw size={15}/> Refresh</button></div>{existingOnline&&!active&&<p className="sensor-warning">A sensor from this computer is already online. Stop its existing PowerShell session before starting another one.</p>}{message&&<p className={failure||controller?.last_error?'sensor-warning':'sensor-message'}>{message}</p>}</div></section><div className="disclaimer"><Shield size={16}/><span><b>Privacy and coverage</b> Network collection is passive and header-only. Optional Windows sign-in, process and endpoint/security events are off until selected. A heartbeat confirms the sensor checked in; it does not confirm full network visibility.</span></div>{user.roles.includes('administrator')&&<SensorRegistry setError={setError}/>}<section className="panel data-panel"><div className="panel-head"><div><h2>Recent sensor sessions</h2><p>Automatically refreshed every four seconds</p></div><span>{sessions.length} sessions</span></div>{sessions.length?<div className="table-wrap"><table><thead><tr><th>SENSOR</th><th>STATE</th><th>LAST SIGNAL</th><th>RECORDS</th><th>SESSION STARTED</th></tr></thead><tbody>{sessions.map(row=><tr key={row.id}><td><b>{row.source_name}</b><small>{row.host_name||'Windows host sensor session'}{row.sensor_id?` · ID ${row.sensor_id.slice(0,8)}`:''}{row.sensor_version?` · v${row.sensor_version}`:''}</small><small>{row.capabilities?.length?row.capabilities.join(' · '):'Legacy session; capabilities not reported'}</small></td><td><span className={`status ${row.state==='online'?'completed':row.state==='stale'?'processing':'disabled'}`}>{row.state==='online'?'Online':row.state==='stale'?'Signal delayed':'Stopped'}</span></td><td>{date(row.last_heartbeat_at)}</td><td>{(row.stats?.accepted||0).toLocaleString()}</td><td>{date(row.started_at)}</td></tr>)}</tbody></table></div>:<Empty text="No sensor sessions yet."/>}</section></div>
}

const discoveryPorts=[{port:22,service:'SSH'},{port:53,service:'DNS'},{port:80,service:'Web (HTTP)'},{port:135,service:'Windows RPC'},{port:139,service:'Windows file sharing'},{port:443,service:'Web (HTTPS)'},{port:445,service:'Windows file sharing'},{port:3389,service:'Remote Desktop'},{port:5432,service:'PostgreSQL'},{port:8000,service:'Web application'},{port:8080,service:'Web application'},{port:8443,service:'Secure web application'}]
function NetworkDiscovery({setError:_setError}:{setError:(s:string)=>void}){
 const[target,setTarget]=useState(''),[ports,setPorts]=useState<number[]>([80,443,445,3389]),[authorized,setAuthorized]=useState(false),[status,setStatus]=useState<Row|null>(null),[busy,setBusy]=useState(false),[message,setMessage]=useState('')
 const refresh=useCallback(async()=>{try{setStatus(await sensorControl<Row>('/network-scan/status'))}catch(error){setStatus(null);setMessage(error instanceof Error?error.message:'Local scanner is unavailable. Start the Windows sensor controller.')}},[])
 useEffect(()=>{void refresh();const timer=window.setInterval(()=>void refresh(),1500);return()=>window.clearInterval(timer)},[refresh])
 async function start(){setBusy(true);setMessage('');try{const result=await sensorControl<Row>('/network-scan/start',{method:'POST',body:JSON.stringify({target,ports,authorized})});setStatus(result)}catch(error){setMessage(error instanceof Error?error.message:'Could not start the network scan.')}finally{setBusy(false)}}
 async function stop(){setBusy(true);try{setStatus(await sensorControl<Row>('/network-scan/stop',{method:'POST',body:'{}'}))}catch(error){setMessage(error instanceof Error?error.message:'Could not stop the scan.')}finally{setBusy(false)}}
 const running=status?.state==='running',progress=status?.total_hosts?Math.min(100,Math.round(status.completed_hosts/status.total_hosts*100)):0
 const portPatterns=(status?.results||[]).map((host:Row)=>host.ports?.filter((item:Row)=>item.state==='open').map((item:Row)=>item.port).sort((a:number,b:number)=>a-b).join(',')||'')
 const uniformOpenPattern=portPatterns.length>=3&&new Set(portPatterns).size===1&&Boolean(portPatterns[0])
  return <div className="content"><Heading eyebrow="AUTHORIZED NETWORK CHECK" title="Network discovery" desc="Find responsive devices and selected common services on a private network you are authorized to check."/><section className="panel discovery-form"><div className="panel-head"><div><h2>{t('Choose the network to check')}</h2><p>{t('The scan runs from this Windows computer, not from the SentinelAI server.')}</p></div><Network size={18}/></div><label className="discovery-target">{t('Private network range')}<input value={target} onChange={event=>setTarget(event.target.value)} placeholder="192.168.1.0/24" disabled={running} autoComplete="off"/><small>{t('Use the network range shown by your router or IT administrator. Maximum 256 addresses; public and link-local ranges are blocked.')}</small></label><div className="discovery-port-label">{t('Services to check')} <small>{t('Choose up to 12 common ports')}</small></div><div className="discovery-ports">{discoveryPorts.map(item=><label key={item.port}><input type="checkbox" checked={ports.includes(item.port)} disabled={running||(!ports.includes(item.port)&&ports.length>=12)} onChange={event=>setPorts(current=>event.target.checked?[...current,item.port]:current.filter(port=>port!==item.port))}/><span>{t(item.service)}</span><code>{item.port}</code></label>)}</div><label className="discovery-consent"><input type="checkbox" checked={authorized} onChange={event=>setAuthorized(event.target.checked)} disabled={running}/><span>{t('I confirm I am authorized to scan this private network.')}</span></label><div className="sensor-actions">{running?<button className="sensor-stop" disabled={busy} onClick={()=>void stop()}><Square size={14}/>{t('Stop scan')}</button>:<button className="primary" disabled={busy||!authorized||!target.trim()||!ports.length} onClick={()=>void start()}><Play size={15}/>{status?.state==='completed'||status?.state==='stopped'?t('Run scan again'):t('Discover devices')}</button>}<button className="secondary" disabled={busy} onClick={()=>void refresh()}><RefreshCw size={15}/>{t('Refresh')}</button></div>{message&&<p className="sensor-warning">{message}</p>}</section><section className="discovery-privacy"><Shield size={16}/><span><b>{t('Safe limits')}</b> {t('TCP responses are checked and selected protocols are probed. Service names are confirmed only when the device replies using that protocol; other open ports are marked unverified.')} {t('ARP host discovery is attempted on directly connected IPv4 networks; selected TCP ports are checked on all target addresses. This scan does not exploit vulnerabilities, log in to devices, or change settings.')}</span></section>{status&&status.state!=='idle'&&<section className="panel discovery-results"><div className="panel-head"><div><h2>{t('Scan results')}</h2><p>{status.target} · {status.completed_hosts||0}/{status.total_hosts||0} {t('addresses checked')} · {status.responsive_hosts??status.results?.length??0} {t('devices responded')} · {status.ports?.length||0} {t('ports selected')} · {t('Scan ID')} {status.scan_id?.slice(0,8)} · {t('Started')} {date(status.started_at)} · {status.duration_seconds??'—'}s</p></div><span className={'status '+(running?'processing':status.state==='completed'?'completed':status.state==='failed'?'failed':'disabled')}>{t(status.state==='running'?'Scanning':status.state==='completed'?'Completed':status.state==='stopped'?'Stopped':status.state==='failed'?'Failed':'Ready')}</span></div>{running&&<div className="discovery-progress"><div><span>{t('Checking devices')} · {status.completed_hosts||0}/{status.total_hosts}</span><b>{progress}%</b></div><i><span style={{width:`${progress}%`}}/></i></div>}{uniformOpenPattern&&<p className="discovery-warning">{t('Several devices reported the same open-port pattern. A firewall or network proxy may be answering for them; verify these results before treating them as services.')}</p>}{status.error&&<p className="sensor-warning">{status.error}</p>}{status.results?.length?<div className="discovery-hosts">{status.results.map((host:Row)=><article key={host.address}><div className="discovery-host-head"><Network size={17}/><b>{host.address}</b><span>{host.state==='up'?t('Host responding'):t('Host status unknown')}</span><span>{host.discovered_by?.includes('ARP')?t('Discovered on local network'):t('Responded on selected ports')}</span><small>{host.ports.filter((item:Row)=>item.state==='open').length} {t('OPEN')} · {host.ports.filter((item:Row)=>item.state==='closed').length} {t('CLOSED')} · {host.ports.filter((item:Row)=>item.state==='filtered').length} {t('FILTERED')}</small></div><div className="discovery-services">{host.ports.map((item:Row)=><span key={item.port} className={`scan-port ${item.state}`}><code>{item.port}</code><b>{t(item.state.toUpperCase())}</b><span>{item.identified?t(item.service):`${t('Service unverified')} · ${t(item.port_hint)}`}</span>{item.product&&<small>{item.product}</small>}</span>)}</div></article>)}</div>:<div className="empty"><div><Search size={17}/></div><p>{running?t('Results will appear as devices respond.'):status.state==='completed'?t('No device response was detected. Hotspot isolation or firewalls can hide devices.'):t('No devices found yet.')}</p></div>}</section>}<div className="discovery-note"><b>{t('What this scan can see')}</b><p>{t('A device appears only when it responds on at least one selected port. Firewalls may hide devices or services, so an empty result does not prove that the network has no devices.')}</p></div></div>
}

function SensorRegistry({setError}:{setError:(s:string)=>void}){
 const[sensors,setSensors]=useState<Row[]>([]),[passwords,setPasswords]=useState<Record<string,string>>({}),[busy,setBusy]=useState(false),[newName,setNewName]=useState(''),[enrolled,setEnrolled]=useState<Row|null>(null)
 // The server returns the generated password once. It is handed to the administrator as a file and never kept in the page afterwards.
 async function enroll(event:React.FormEvent){event.preventDefault();if(!newName.trim())return;setBusy(true);try{const created=await api<Row>('/ingest/live/sensors/enrollment',{method:'POST',body:JSON.stringify({name:newName.trim()})});setEnrolled(created);setNewName('')}catch(e){setError(e instanceof Error?e.message:'Unable to create sensor credentials')}finally{setBusy(false)}}
 function downloadCredentials(){if(!enrolled)return;const blob=new Blob([JSON.stringify({email:enrolled.email,password:enrolled.password,name:enrolled.name},null,2)],{type:'application/json'});const link=document.createElement('a');link.href=URL.createObjectURL(blob);link.download='sensor-credentials.json';link.click();URL.revokeObjectURL(link.href);setEnrolled(null)}
 const load=useCallback(async()=>{try{setSensors(await api<Row[]>('/ingest/live/sensors'))}catch(e){setError(e instanceof Error?e.message:'Unable to load registered sensors')}},[setError])
 useEffect(()=>{void load()},[load])
 async function revoke(sensorId:string){if(!window.confirm('Revoke this sensor? API access stops immediately; a running process exits after its next heartbeat (within 10 seconds).'))return;setBusy(true);try{await api('/ingest/live/sensors/'+sensorId+'/revoke',{method:'POST'});await load()}catch(e){setError(e instanceof Error?e.message:'Unable to revoke sensor')}finally{setBusy(false)}}
 async function rotate(sensorId:string){const password=passwords[sensorId]||'';if(password.length<12){setError('Sensor passwords must be at least 12 characters.');return}setBusy(true);try{await api('/ingest/live/sensors/'+sensorId+'/rotate-credential',{method:'POST',body:JSON.stringify({password})});setPasswords(current=>({...current,[sensorId]:''}));await load();setError('Sensor credential rotated. Update SENTINEL_SENSOR_PASSWORD in the host .env file and restart its controller.')}catch(e){setError(e instanceof Error?e.message:'Unable to rotate sensor credential')}finally{setBusy(false)}}
 return <details open className="panel data-panel sensor-registry"><summary className="panel-head"><div><h2>Registered sensors</h2><p>Enrollment, last check-in, and credential lifecycle</p></div><button className="icon-button" aria-label="Refresh registered sensors" onClick={event=>{event.stopPropagation();void load()}} disabled={busy}><RefreshCw size={16}/></button></summary><form className="case-note-form" onSubmit={enroll} style={{padding:'0 18px 14px'}}><label>Add a sensor computer<input value={newName} onChange={event=>setNewName(event.target.value)} maxLength={80} placeholder="A name for the computer, for example Accounting PC" disabled={busy}/></label><button className="secondary" disabled={busy||!newName.trim()}>Create sensor credentials</button>{enrolled&&<div className="lab-note"><b>Credentials created for {enrolled.name}</b><p>Account {enrolled.email}. Download the file now: the password is shown only this once and cannot be recovered. Put <code>sensor-credentials.json</code> in the sensor folder on that computer, next to <code>start.ps1</code>. Treat it like a password.</p><button type="button" className="primary" onClick={downloadCredentials}>Download sensor-credentials.json</button></div>}<small>Each computer needs its own credentials. The sensor program itself comes from <code>scripts\package_sensor.ps1</code>; see “Sensors on other computers” in the operations guide.</small></form>{sensors.length?<div className="table-wrap"><table><thead><tr><th>SENSOR</th><th>CREDENTIAL</th><th>STATUS</th><th>LAST SIGNAL</th><th>ACCESS</th></tr></thead><tbody>{sensors.map(sensor=><tr key={sensor.sensor_id}><td><b>{sensor.host_name||sensor.source_name}</b><small>{sensor.sensor_id}</small><small>{sensor.sensor_version?'v'+sensor.sensor_version+' · ':''}{sensor.capabilities?.join(' · ')||'No capabilities reported'}</small></td><td>{sensor.credential_email}</td><td><span className={'status '+(sensor.status==='active'?'completed':'disabled')}>{sensor.status}</span></td><td>{date(sensor.last_seen_at)}</td><td><div className="sensor-registry-actions">{sensor.status==='active'?<><input aria-label={'New password for '+sensor.credential_email} type="password" autoComplete="new-password" minLength={12} placeholder="New password (12+)" value={passwords[sensor.sensor_id]||''} onChange={event=>setPasswords(current=>({...current,[sensor.sensor_id]:event.target.value}))}/><button className="secondary" disabled={busy||!(passwords[sensor.sensor_id]||'').length} onClick={()=>void rotate(sensor.sensor_id)}>Rotate</button><button className="sensor-stop" disabled={busy} onClick={()=>void revoke(sensor.sensor_id)}>Revoke</button></>:<span>{date(sensor.revoked_at)}</span>}</div></td></tr>)}</tbody></table></div>:<Empty text="No sensors have enrolled yet."/>}</details>
}
